import{_ as e,c as i,o,ae as r}from"./chunks/framework.BQlYxExx.js";const n="/images/legenda-event-storming.png",t="/images/rejestracja-logowanie-uzytkownik.png",s="/images/rejestracja-logowanie-schronisko.png",c="/images/aktualizacja-profilu-u%C5%BCytkownika.png",z="/images/konfiguracja-preferencji-adopcyjnych.png",l="/images/import_crawling.png",w="/images/zapisywanie_zdjec_storage.png",g=JSON.parse('{"title":"Sesja Event Storming / User Stories","description":"","frontmatter":{},"headers":[],"relativePath":"event-storming.md","filePath":"event-storming.md"}'),p={name:"event-storming.md"};function y(k,a,d,m,u,j){return o(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="sesja-event-storming-user-stories" tabindex="-1">Sesja Event Storming / User Stories <a class="header-anchor" href="#sesja-event-storming-user-stories" aria-label="Permalink to &quot;Sesja Event Storming / User Stories&quot;">​</a></h1><h2 id="_4-1-event-storming" tabindex="-1">4.1. Event Storming <a class="header-anchor" href="#_4-1-event-storming" aria-label="Permalink to &quot;4.1. Event Storming&quot;">​</a></h2><p>Sesja Event Storming została przeprowadzona online za pomocą narzędzia Miro. Celem sesji było zidentyfikowanie kluczowych zdarzeń biznesowych (Events), komend wyzwalających akcje (Commands), reguł biznesowych (Policies) oraz granic agregatów w domenie systemu <em>ŁapGo</em>.</p><p><img src="'+n+'" alt="Legenda notacji wykorzystanej podczas sesji Event Storming."><em>Rysunek 1: Legenda notacji wykorzystanej podczas sesji Event Storming.</em></p><h3 id="kluczowe-procesy-biznesowe" tabindex="-1">Kluczowe Procesy Biznesowe <a class="header-anchor" href="#kluczowe-procesy-biznesowe" aria-label="Permalink to &quot;Kluczowe Procesy Biznesowe&quot;">​</a></h3><p>Na podstawie przeprowadzonych prac wyróżniono następujące procesy:</p><h4 id="_1-rejestracja-i-autoryzacja" tabindex="-1">1. Rejestracja i Autoryzacja <a class="header-anchor" href="#_1-rejestracja-i-autoryzacja" aria-label="Permalink to &quot;1. Rejestracja i Autoryzacja&quot;">​</a></h4><p>Proces obejmuje dwa główne flow: dla standardowego Użytkownika oraz dla Schroniska. W obu przypadkach kluczowa jest weryfikacja adresu e-mail oraz obsługa błędnego logowania.</p><p><img src="'+t+'" alt="Flow rejestracji i logowania użytkownika z uwzględnieniem przywracania sesji."><em>Rysunek 2: Flow rejestracji i logowania użytkownika z uwzględnieniem przywracania sesji.</em></p><p>W przypadku Schroniska proces jest rozszerzony o dedykowany krok weryfikacji placówki, co ma na celu zapewnienie bezpieczeństwa zwierząt.</p><p><img src="'+s+'" alt="Proces rejestracji schroniska wymagający dodatkowej weryfikacji danych przez system."><em>Rysunek 3: Proces rejestracji schroniska wymagający dodatkowej weryfikacji danych przez system.</em></p><h4 id="_2-zarzadzanie-profilem-i-preferencjami" tabindex="-1">2. Zarządzanie Profilem i Preferencjami <a class="header-anchor" href="#_2-zarzadzanie-profilem-i-preferencjami" aria-label="Permalink to &quot;2. Zarządzanie Profilem i Preferencjami&quot;">​</a></h4><p>Użytkownicy mogą aktualizować swoje dane oraz definiować preferencje adopcyjne (gatunek, wiek, wielkość). Zmiana preferencji automatycznie wpływa na widok dopasowanych zwierząt.</p><p><img src="'+c+'" alt="Procesy aktualizacji profilu oraz konfiguracji filtrów dopasowań."><img src="'+z+'" alt="Procesy aktualizacji profilu oraz konfiguracji filtrów dopasowań."><em>Rysunek 4: Procesy aktualizacji profilu oraz konfiguracji filtrów dopasowań.</em></p><h4 id="_3-import-i-agregacja-danych" tabindex="-1">3. Import i Agregacja Danych <a class="header-anchor" href="#_3-import-i-agregacja-danych" aria-label="Permalink to &quot;3. Import i Agregacja Danych&quot;">​</a></h4><p>System automatycznie pobiera dane z zewnętrznych witryn schronisk. Proces ten obejmuje analizę strony, mapowanie pól na model wewnętrzny oraz pobieranie i zapisywanie zdjęć do magazynu (Storage/CDN).</p><p><img src="'+l+'" alt="Automatyczny proces importu zwierząt z zewnętrznych źródeł (Crawlery)."><em>Rysunek 5: Automatyczny proces importu zwierząt z zewnętrznych źródeł (Crawlery).</em></p><p><img src="'+w+'" alt="Szczegółowy proces przetwarzania i zapisu multimediów."><em>Rysunek 6: Szczegółowy proces przetwarzania i zapisu multimediów.</em></p><h3 id="kluczowe-zdarzenia-domenowe-events" tabindex="-1">Kluczowe Zdarzenia Domenowe (Events) <a class="header-anchor" href="#kluczowe-zdarzenia-domenowe-events" aria-label="Permalink to &quot;Kluczowe Zdarzenia Domenowe (Events)&quot;">​</a></h3><p>Zidentyfikowane zdarzenia o największym znaczeniu dla logiki aplikacji:</p><ul><li><strong>Zwierzak Wykryty i Zmapowany</strong>: Moment poprawnego sparsowania danych przez crawler.</li><li><strong>Zdjęcia Zwierzaka Pobrane i Zapisane</strong>: Potwierdzenie dostępności zasobów multimedialnych.</li><li><strong>Preferencje Zaaktualizowane</strong>: Wyzwalacz dla algorytmu dopasowującego ogłoszenia.</li><li><strong>Schronisko Zweryfikowane</strong>: Decyzja administracyjna dopuszczająca schronisko do publikacji własnych ofert.</li></ul><h2 id="_4-2-user-stories" tabindex="-1">4.2. User Stories <a class="header-anchor" href="#_4-2-user-stories" aria-label="Permalink to &quot;4.2. User Stories&quot;">​</a></h2><p>Poniżej przedstawiono kluczowe historyjki użytkownika, które stanowią podstawę do tworzenia i priorytetyzacji backlogu projektu ŁapGo.</p><h3 id="kluczowe-historyjki-adopcyjne" tabindex="-1">Kluczowe Historyjki Adopcyjne <a class="header-anchor" href="#kluczowe-historyjki-adopcyjne" aria-label="Permalink to &quot;Kluczowe Historyjki Adopcyjne&quot;">​</a></h3><ul><li>Jako Użytkownik, chcę ustawić szczegółowe preferencje (gatunek, wiek, wielkość, płeć), aby system mógł dopasować ogłoszenia spełniające moje oczekiwania.</li><li>Jako Użytkownik, chcę zobaczyć listę zwierząt dopasowanych do moich preferencji, aby łatwo znaleźć potencjalnego nowego pupila.</li><li>Jako Użytkownik, chcę filtrować i sortować wyniki wyszukiwania (np. po lokalizacji, dacie dodania), aby zawęzić opcje i znaleźć ogłoszenia z najbliższych schronisk.</li><li>Jako Użytkownik, chcę dodać zwierzę do listy ulubionych, aby szybko wrócić do interesujących mnie ogłoszeń i je porównać.</li><li>Jako Użytkownik, chcę wyświetlić dane kontaktowe schroniska na stronie zwierzęcia, aby szybko nawiązać bezpośredni kontakt w sprawie adopcji.</li></ul><h3 id="historyjki-panelu-uzytkownika-i-administracji" tabindex="-1">Historyjki Panelu Użytkownika i Administracji <a class="header-anchor" href="#historyjki-panelu-uzytkownika-i-administracji" aria-label="Permalink to &quot;Historyjki Panelu Użytkownika i Administracji&quot;">​</a></h3><ul><li>Jako Użytkownik, chcę zarejestrować się i zalogować do aplikacji, aby móc zapisywać preferencje i ulubione zwierzęta.</li><li>Jako Schronisko (zweryfikowany użytkownik), chcę dodać własne zwierzęta do adopcji, aby moje ogłoszenia były widoczne w centralnej bazie.</li><li>Jako Administrator, chcę ręcznie weryfikować ogłoszenia z agregatora, aby zapewnić wysoką jakość i aktualność prezentowanych danych.</li><li>Jako Administrator, chcę zmienić status adopcyjny zwierzęcia (np. na &quot;Adoptowany&quot;), aby ogłoszenie przestało być aktywnie wyświetlane użytkownikom.</li></ul><h3 id="historyjki-techniczne-scraping-ai" tabindex="-1">Historyjki Techniczne (Scraping/AI) <a class="header-anchor" href="#historyjki-techniczne-scraping-ai" aria-label="Permalink to &quot;Historyjki Techniczne (Scraping/AI)&quot;">​</a></h3><ul><li>Jako System, chcę używać scrapera opartego na AI (API Gemini) do inteligentnego pobierania i strukturyzowania danych ze stron schronisk.</li><li>Jako System, chcę używać geolokalizacji i map do wyświetlania schronisk na mapie i dopasowywania zwierząt na podstawie odległości.</li></ul>',29)])])}const b=e(p,[["render",y]]);export{g as __pageData,b as default};
